/* Adapted controls; original room coordinates and routing algorithms are unchanged. */
const MAP_STATE_KEY='congreso-map-view-v2';let activeFloor='1',hasRoute=false,originChosen=false;
const box=document.querySelector('.route-box'),content=document.querySelector('.content');
const destinationLabel=document.createElement('label');destinationLabel.htmlFor='routeDestination';destinationLabel.className='destination-label';destinationLabel.textContent='¿A qué salón vas?';
const directions=document.createElement('details');directions.className='directions';const summary=document.createElement('summary');summary.textContent='Cómo llegar';directions.append(summary);
const originLabel=document.createElement('label');originLabel.htmlFor='routeOrigin';originLabel.textContent='¿Desde dónde sales?';
const originHelp=document.createElement('small');originHelp.textContent='Elige tu punto de partida. No detectamos tu ubicación.';
directions.append(originLabel,routeOrigin,originHelp,showRouteBtn);
const status=document.createElement('div');status.className='route-summary-line';routeStatus.setAttribute('aria-live','polite');status.append(routeStatus,clearRouteBtn);
box.replaceChildren(destinationLabel,routeDestination,directions);box.className='destination-card';
const tools=document.querySelector('.map-tools');document.querySelector('.floor-switch').after(tools);
const floorHint=document.createElement('div');floorHint.className='floor-hint';tools.before(floorHint);content.prepend(status);
showRouteBtn.textContent='Mostrar recorrido';clearRouteBtn.textContent='Quitar recorrido';document.querySelector('#zoomReset').textContent='Ver plano completo';
function notifyDestination(){parent.postMessage({type:'congress-map-destination',roomId:routeDestination.value.startsWith('r:')?routeDestination.value.slice(2):null},location.origin);}
function updateMapHeight(){parent.postMessage({type:'congress-map-height',height:Math.ceil(document.body.getBoundingClientRect().height)},location.origin);}
function saveMapView(){try{sessionStorage.setItem(MAP_STATE_KEY,JSON.stringify({origin:originChosen?routeOrigin.value:'',destination:routeDestination.value,floor:activeFloor,zoom,drawn:hasRoute}));}catch{}}
function destinationInfo(){const [kind,id]=routeDestination.value.split(':');if(kind==='r')return getRoomDestination(id);if(kind==='s')return {floor:1};if(kind==='a'&&routeAliases[id]?.target)return getRoomDestination(routeAliases[id].target);return null;}
function updateControls(){const dest=destinationInfo(),other=dest&&activeFloor!=='both'&&String(dest.floor)!==activeFloor;clearRouteBtn.hidden=!hasRoute;summary.textContent=originChosen?'Desde: '+routeOrigin.selectedOptions[0].textContent+' · Cambiar':'Cómo llegar';floorHint.replaceChildren();const label=document.createElement('span');label.textContent=activeFloor==='both'?'Viendo ambas plantas':activeFloor==='1'?'Viendo planta baja':'Viendo planta alta';floorHint.append(label);if(other){const b=document.createElement('button');b.textContent='Destino en planta '+(dest.floor===1?'baja':'alta')+' →';b.addEventListener('click',()=>setFloor(String(dest.floor)));floorHint.append(b);}else if(hasRoute&&routeLayer1.children.length&&routeLayer2.children.length&&activeFloor!=='both'){const b=document.createElement('button');b.textContent='Ver tramo en planta '+(activeFloor==='1'?'alta':'baja')+' →';b.addEventListener('click',()=>setFloor(activeFloor==='1'?'2':'1'));floorHint.append(b);}notifyDestination();}
function setFloor(value){activeFloor=value;document.querySelectorAll('[data-map-floor]').forEach(e=>e.hidden=value!=='both'&&e.dataset.mapFloor!==value);document.querySelectorAll('[data-floor]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.floor===value)));updateControls();saveMapView();updateMapHeight();}
function highlightRoom(id){document.querySelectorAll('[data-room-id]').forEach(e=>e.classList.toggle('chosen-room',e.dataset.roomId===id));}
function destinationChanged(){hasRoute=false;clearRoute();highlightRoom(routeDestination.value.startsWith('r:')?routeDestination.value.slice(2):null);const dest=destinationInfo();routeStatus.textContent=routeDestination.value?'Destino: '+routeDestination.selectedOptions[0].textContent:'Selecciona un salón para ubicarlo.';if(dest)setFloor(String(dest.floor));else{updateControls();saveMapView();}directions.open=false;updateMapHeight();}
function chooseRoom(id){if(![...routeDestination.options].some(o=>o.value==='r:'+id))return;routeDestination.value='r:'+id;destinationChanged();}
document.querySelectorAll('[data-floor]').forEach(e=>e.addEventListener('click',()=>setFloor(e.dataset.floor)));
routeDestination.addEventListener('change',destinationChanged);
routeOrigin.addEventListener('change',()=>{originChosen=!!routeOrigin.value;hasRoute=false;clearRoute();routeStatus.textContent=originChosen?'Origen actualizado. Pulsa Mostrar recorrido.':'Elige un origen para calcular el recorrido.';updateControls();saveMapView();});
showRouteBtn.addEventListener('click',e=>{if(!originChosen||!routeOrigin.value||!routeDestination.value){e.preventDefault();e.stopImmediatePropagation();routeStatus.textContent=!routeDestination.value?'Selecciona un destino.':'Selecciona desde dónde sales.';(!routeDestination.value?routeDestination:routeOrigin).focus();}},true);
showRouteBtn.addEventListener('click',()=>{hasRoute=routeLayer1.children.length+routeLayer2.children.length>0;directions.open=false;setFloor(String(getOriginLoc().floor));saveMapView();updateMapHeight();});
clearRouteBtn.addEventListener('click',()=>{hasRoute=false;routeStatus.textContent=routeDestination.value?'Destino: '+routeDestination.selectedOptions[0].textContent:'Selecciona un salón.';updateControls();saveMapView();});
// Preserve the visual centre while zooming either floor.
const originalSetZoom=setZoom;setZoom=function(v){const containers=[...document.querySelectorAll('.map-scroll')],ratios=containers.map(e=>[(e.scrollLeft+e.clientWidth/2)/Math.max(1,e.scrollWidth),(e.scrollTop+e.clientHeight/2)/Math.max(1,e.scrollHeight)]);originalSetZoom(v);requestAnimationFrame(()=>{containers.forEach((e,i)=>{e.scrollLeft=ratios[i][0]*e.scrollWidth-e.clientWidth/2;e.scrollTop=ratios[i][1]*e.scrollHeight-e.clientHeight/2;});saveMapView();updateMapHeight();});};
directions.addEventListener('toggle',updateMapHeight);document.querySelectorAll('.map-tools button').forEach(e=>e.addEventListener('click',saveMapView));
let saved;try{saved=JSON.parse(sessionStorage.getItem(MAP_STATE_KEY)||'null');}catch{}
routeOrigin.value='';if(saved){if([...routeOrigin.options].some(o=>o.value===saved.origin)){routeOrigin.value=saved.origin;originChosen=!!saved.origin;}if([...routeDestination.options].some(o=>o.value===saved.destination))routeDestination.value=saved.destination;setZoom(Number(saved.zoom)||100);if(saved.drawn&&originChosen&&routeDestination.value){showRoute();hasRoute=true;}else routeStatus.textContent=routeDestination.value?'Destino: '+routeDestination.selectedOptions[0].textContent:'Selecciona un salón.';highlightRoom(routeDestination.value.slice(2));setFloor(['1','2','both'].includes(saved.floor)?saved.floor:'1');}else{routeStatus.textContent='Selecciona un salón para ubicarlo.';setFloor('1');}
const requested=new URLSearchParams(location.search).get('room');if(requested&&routeDestination.value!=='r:'+requested)chooseRoom(requested);
new ResizeObserver(updateMapHeight).observe(document.body);window.addEventListener('load',updateMapHeight);document.querySelectorAll('img,image').forEach(e=>e.addEventListener('load',updateMapHeight));document.body.dataset.mapReady='true';
